class Solution {
public:
    int minTimeToType(string word) {
        int total = 0;
        char cur = 'a';
        for (char c : word) {
            int diff = abs(c - cur);
            int dist = min(diff, 26 - diff);
            total += dist + 1;
            cur = c;
        }
        return total;
    }
};
